import { colors, fontSizes, radius, shadows, spacing, washCss } from './values';

/**
 * Builds tokens.css: a Tailwind v4 `@theme` block, so classes like `bg-ink`, `text-sub`,
 * `rounded-pill` and `font-sans` work in every web app that imports it.
 */
export function buildTokensCss(): string {
  const lines: string[] = [
    '/* Generated by @shopinbos/tokens (scripts/write-css.ts). Do not edit by hand. */',
    '@theme {',
  ];
  for (const [name, hex] of Object.entries(colors)) lines.push(`  --color-${name}: ${hex};`);
  lines.push(`  --font-sans: var(--font-jakarta), 'Plus Jakarta Sans', system-ui, sans-serif;`);
  for (const [name, px] of Object.entries(fontSizes))
    lines.push(`  --text-${name}: ${px / 16}rem;`);
  lines.push(`  --radius-sm: ${radius.sm}px;`);
  lines.push(`  --radius-md: ${radius.md}px;`);
  lines.push(`  --radius-card: ${radius.cardWeb}px;`);
  lines.push(`  --radius-card-mobile: ${radius.cardMobile}px;`);
  lines.push(`  --radius-pill: ${radius.pill}px;`);
  lines.push(`  --shadow-card: ${shadows.card};`);
  lines.push(`  --shadow-floating: ${shadows.floating};`);
  lines.push('}', '', ':root {');
  for (const [step, px] of Object.entries(spacing)) lines.push(`  --sb-space-${step}: ${px}px;`);
  lines.push(`  --sb-wash: ${washCss};`);
  lines.push('}', '');
  return lines.join('\n');
}
